    "statement": "Cho tam giác $ABC$ vuông tại $A$ có $AB = 6$ cm, $AC = 8$ cm. Tính độ dài cạnh huyền $BC$ và độ dài đường cao $AH$.",
    "language": "vi",
    "topic": "geometry",
    "subtopic": "tam_giac_vuong_hệ_thức_lượng",
    "gradeLevel": 9,
    "withinCurriculum": true,
    "concepts": ["tam giác vuông", "định lý Py-ta-go", "hệ thức lượng trong tam giác vuông"],
    "givens": [
      "Tam giác $ABC$ vuông tại $A$",
      "Cạnh $AB = 6$ cm",
      "Cạnh $AC = 8$ cm",
      "$AH$ là đường cao ($AH \\perp BC$)"
    ],
    "unknowns": [
      "Độ dài cạnh $BC$",
      "Độ dài đường cao $AH$"
    ],
